import{_ as e,a0 as D,w as A,s as R,ao as r,I as n,x as l,a1 as t,A as I}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Linux 下使用 RAID（一）：介紹 RAID 的級別和概念 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（一）：介紹 RAID 的級別和概念 | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（一）：介紹 RAID 的級別和概念 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（一）：介紹 RAID 的級別和概念 | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 1 - Introduction to RAID, Concepts of RAID and RAID Levels","title":"在 Linux 下使用 RAID（一）：介紹 RAID 的級別和概念","tag":"RAID","desc":""},"relativePath":"RAID/Part 1 - Introduction to RAID, Concepts of RAID and RAID Levels.md","filePath":"[post].md"}'),p={name:"RAID/Part 1 - Introduction to RAID, Concepts of RAID and RAID Levels.md"};function o(s,i,d,u,m,g){const a=D("Link");return A(),R("div",null,[i[13]||(i[13]=r('<h1 id="在-linux-下使用-raid-一-介紹-raid-的級別和概念" tabindex="-1">在 Linux 下使用 RAID（一）：介紹 RAID 的級別和概念 <a class="header-anchor" href="#在-linux-下使用-raid-一-介紹-raid-的級別和概念" aria-label="Permalink to “在 Linux 下使用 RAID（一）：介紹 RAID 的級別和概念”">​</a></h1><p>RAID 的意思是廉價磁盤冗餘陣列（Redundant Array of Inexpensive Disks），但現在它被稱為獨立磁盤冗餘陣列（Redundant Array of Independent Drives）。早先一個容量很小的磁盤都是非常昂貴的，但是現在我們可以很便宜的買到一個更大的磁盤。Raid 是一系列放在一起，成為一個邏輯卷的磁盤集合。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/RAID.jpg" alt="RAID in Linux"></p><p><em>在 Linux 中理解 RAID 設置</em></p><p>RAID 包含一組或者一個集合甚至一個陣列。使用一組磁盤結合驅動器組成 RAID 陣列或 RAID 集。將至少兩個磁盤連接到一個 RAID 控制器，而成為一個邏輯卷，也可以將多個驅動器放在一個組中。一組磁盤只能使用一個 RAID 級別。使用 RAID 可以提高服務器的性能。不同 RAID 的級別，性能會有所不同。它通過容錯和高可用性來保存我們的數據。</p><p>這個系列被命名為“在 Linux 下使用 RAID”，分為9個部分，包括以下主題：</p><ul><li>第1部分：介紹 RAID 的級別和概念</li><li>第2部分：在Linux中如何設置 RAID0（條帶化）</li><li>第3部分：在Linux中如何設置 RAID1（鏡像化）</li><li>第4部分：在Linux中如何設置 RAID5（條帶化與分佈式奇偶校驗）</li><li>第5部分：在Linux中如何設置 RAID6（條帶雙分佈式奇偶校驗）</li><li>第6部分：在Linux中設置 RAID 10 或1 + 0（嵌套）</li><li>第7部分：增加現有的 RAID 陣列並刪除損壞的磁盤</li><li>第8部分：在 RAID 中恢復（重建）損壞的驅動器</li><li>第9部分：在 Linux 中管理 RAID</li></ul><p>這是9篇系列教程的第1部分，在這裏我們將介紹 RAID 的概念和 RAID 級別，這是在 Linux 中構建 RAID 需要理解的。</p><h3 id="軟件-raid-和硬件-raid" tabindex="-1">軟件 RAID 和硬件 RAID <a class="header-anchor" href="#軟件-raid-和硬件-raid" aria-label="Permalink to “軟件 RAID 和硬件 RAID”">​</a></h3><p>軟件 RAID 的性能較低，因為其使用主機的資源。 需要加載 RAID 軟件以從軟件 RAID 卷中讀取數據。在加載 RAID 軟件前，操作系統需要引導起來才能加載 RAID 軟件。在軟件 RAID 中無需物理硬件。零成本投資。</p><p>硬件 RAID 的性能較高。他們採用 PCI Express 卡物理地提供有專用的 RAID 控制器。它不會使用主機資源。他們有 NVRAM 用於緩存的讀取和寫入。緩存用於 RAID 重建時，即使出現電源故障，它會使用後備的電池電源保持緩存。對於大規模使用是非常昂貴的投資。</p><p>硬件 RAID 卡如下所示：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Hardware-RAID.jpg" alt="Hardware RAID"></p><p><em>硬件 RAID</em></p><h4 id="重要的-raid-概念" tabindex="-1">重要的 RAID 概念 <a class="header-anchor" href="#重要的-raid-概念" aria-label="Permalink to “重要的 RAID 概念”">​</a></h4><ul><li><strong>校驗</strong>方式用在 RAID 重建中從校驗所保存的信息中重新生成丟失的內容。 RAID 5，RAID 6 基於校驗。</li><li><strong>條帶化</strong>是將切片數據隨機存儲到多個磁盤。它不會在單個磁盤中保存完整的數據。如果我們使用2個磁盤，則每個磁盤存儲我們的一半數據。</li><li><strong>鏡像</strong>被用於 RAID 1 和 RAID 10。鏡像會自動備份數據。在 RAID 1 中，它會保存相同的內容到其他盤上。</li><li><strong>熱備份</strong>只是我們的服務器上的一個備用驅動器，它可以自動更換髮生故障的驅動器。在我們的陣列中，如果任何一個驅動器損壞，熱備份驅動器會自動用於重建 RAID。</li><li><strong>塊</strong>是 RAID 控制器每次讀寫數據時的最小單位，最小 4KB。通過定義塊大小，我們可以增加 I/O 性能。</li></ul><p>RAID有不同的級別。在這裏，我們僅列出在真實環境下的使用最多的 RAID 級別。</p><ul><li>RAID0 = 條帶化</li><li>RAID1 = 鏡像</li><li>RAID5 = 單磁盤分佈式奇偶校驗</li><li>RAID6 = 雙磁盤分佈式奇偶校驗</li><li>RAID10 = 鏡像 + 條帶。（嵌套RAID）</li></ul><p>RAID 在大多數 Linux 發行版上使用名為 mdadm 的軟件包進行管理。讓我們先對每個 RAID 級別認識一下。</p><h4 id="raid-0-條帶化" tabindex="-1">RAID 0 / 條帶化 <a class="header-anchor" href="#raid-0-條帶化" aria-label="Permalink to “RAID 0 / 條帶化”">​</a></h4><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/RAID_0.svg/150px-RAID_0.svg.png" alt=""></p><p>條帶化有很好的性能。在 RAID 0（條帶化）中數據將使用切片的方式被寫入到磁盤。一半的內容放在一個磁盤上，另一半內容將被寫入到另一個磁盤。</p><p>假設我們有2個磁盤驅動器，例如，如果我們將數據“TECMINT”寫到邏輯卷中，“T”將被保存在第一盤中，“E”將保存在第二盤，&#39;C&#39;將被保存在第一盤，“M”將保存在第二盤，它會一直繼續此循環過程。（LCTT 譯註：實際上不可能按字節切片，是按數據塊切片的。）</p><p>在這種情況下，如果驅動器中的任何一個發生故障，我們就會丟失數據，因為一個盤中只有一半的數據，不能用於重建 RAID。不過，當比較寫入速度和性能時，RAID 0 是非常好的。創建 RAID 0（條帶化）至少需要2個磁盤。如果你的數據是非常寶貴的，那麼不要使用此 RAID 級別。</p><ul><li>高性能。</li><li>RAID 0 中容量零損失。</li><li>零容錯。</li><li>寫和讀有很高的性能。</li></ul><h4 id="raid-1-鏡像化" tabindex="-1">RAID 1 / 鏡像化 <a class="header-anchor" href="#raid-1-鏡像化" aria-label="Permalink to “RAID 1 / 鏡像化”">​</a></h4><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/RAID_1.svg/150px-RAID_1.svg.png" alt=""></p><p>鏡像也有不錯的性能。鏡像可以對我們的數據做一份相同的副本。假設我們有兩個2TB的硬盤驅動器，我們總共有4TB，但在鏡像中，但是放在 RAID 控制器後面的驅動器形成了一個邏輯驅動器，我們只能看到這個邏輯驅動器有2TB。</p><p>當我們保存數據時，它將同時寫入這兩個2TB驅動器中。創建 RAID 1（鏡像化）最少需要兩個驅動器。如果發生磁盤故障，我們可以通過更換一個新的磁盤恢復 RAID 。如果在 RAID 1 中任何一個磁盤發生故障，我們可以從另一個磁盤中獲取相同的數據，因為另外的磁盤中也有相同的數據。所以是零數據丟失。</p><ul><li>良好的性能。</li><li>總容量丟失一半可用空間。</li><li>完全容錯。</li><li>重建會更快。</li><li>寫性能變慢。</li><li>讀性能變好。</li><li>能用於操作系統和小規模的資料庫。</li></ul><h4 id="raid-5-分佈式奇偶校驗" tabindex="-1">RAID 5 / 分佈式奇偶校驗 <a class="header-anchor" href="#raid-5-分佈式奇偶校驗" aria-label="Permalink to “RAID 5 / 分佈式奇偶校驗”">​</a></h4><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/RAID_5.svg/300px-RAID_5.svg.png" alt=""></p><p>RAID 5 多用於企業級。 RAID 5 的以分佈式奇偶校驗的方式工作。奇偶校驗信息將被用於重建數據。它從剩下的正常驅動器上的信息來重建。在驅動器發生故障時，這可以保護我們的數據。</p><p>假設我們有4個驅動器，如果一個驅動器發生故障而後我們更換髮生故障的驅動器後，我們可以從奇偶校驗中重建數據到更換的驅動器上。奇偶校驗信息存儲在所有的4個驅動器上，如果我們有4個 1TB 的驅動器。奇偶校驗信息將被存儲在每個驅動器的256G中，而其它768GB是用户自己使用的。單個驅動器故障後，RAID 5 依舊正常工作，如果驅動器損壞個數超過1個會導致數據的丟失。</p><ul><li>性能卓越</li><li>讀速度將非常好。</li><li>寫速度處於平均水準，如果我們不使用硬件 RAID 控制器，寫速度緩慢。</li><li>從所有驅動器的奇偶校驗信息中重建。</li><li>完全容錯。</li><li>1個磁盤空間將用於奇偶校驗。</li><li>可以被用在文件服務器，Web服務器，非常重要的備份中。</li></ul><h4 id="raid-6-雙分佈式奇偶校驗磁盤" tabindex="-1">RAID 6 雙分佈式奇偶校驗磁盤 <a class="header-anchor" href="#raid-6-雙分佈式奇偶校驗磁盤" aria-label="Permalink to “RAID 6 雙分佈式奇偶校驗磁盤”">​</a></h4><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/RAID_6.svg/300px-RAID_6.svg.png" alt=""></p><p>RAID 6 和 RAID 5 相似但它有兩個分佈式奇偶校驗。大多用在大數量的陣列中。我們最少需要4個驅動器，即使有2個驅動器發生故障，我們依然可以更換新的驅動器後重建數據。</p><p>它比 RAID 5 慢，因為它將數據同時寫到4個驅動器上。當我們使用硬件 RAID 控制器時速度就處於平均水準。如果我們有6個的1TB驅動器，4個驅動器將用於數據保存，2個驅動器將用於校驗。</p><ul><li>性能不佳。</li><li>讀的性能很好。</li><li>如果我們不使用硬件 RAID 控制器寫的性能會很差。</li><li>從兩個奇偶校驗驅動器上重建。</li><li>完全容錯。</li><li>2個磁盤空間將用於奇偶校驗。</li><li>可用於大型陣列。</li><li>用於備份和視頻流中，用於大規模。</li></ul><h4 id="raid-10-鏡像-條帶" tabindex="-1">RAID 10 / 鏡像+條帶 <a class="header-anchor" href="#raid-10-鏡像-條帶" aria-label="Permalink to “RAID 10 / 鏡像+條帶”">​</a></h4><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/RAID_10_01.svg/300px-RAID_10_01.svg.png" alt=""></p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/RAID_01.svg/300px-RAID_01.svg.png" alt=""></p><p>RAID 10 可以被稱為1 + 0或0 +1。它將做鏡像+條帶兩個工作。在 RAID 10 中首先做鏡像然後做條帶。在 RAID 01 上首先做條帶，然後做鏡像。RAID 10 比 01 好。</p><p>假設，我們有4個驅動器。當我邏輯捲上寫數據時，它會使用鏡像和條帶的方式將數據保存到4個驅動器上。</p><p>如果我在 RAID 10 上寫入數據“TECMINT”，數據將使用如下方式保存。首先將“T”同時寫入兩個磁盤，“E”也將同時寫入另外兩個磁盤，所有數據都寫入兩塊磁盤。這樣可以將每個數據複製到另外的磁盤。</p><p>同時它將使用 RAID 0 方式寫入數據，遵循將“T”寫入第一組盤，“E”寫入第二組盤。再次將“C”寫入第一組盤，“M”到第二組盤。</p><ul><li>良好的讀寫性能。</li><li>總容量丟失一半的可用空間。</li><li>容錯。</li><li>從副本數據中快速重建。</li><li>由於其高性能和高可用性，常被用於資料庫的存儲中。</li></ul><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這篇文章中，我們已經瞭解了什麼是 RAID 和在實際環境大多采用哪個級別的 RAID。希望你已經學會了上面所寫的。對於 RAID 的構建必須瞭解有關 RAID 的基本知識。以上內容可以基本滿足你對 RAID 的瞭解。</p><p>在接下來的文章中，我將介紹如何設置和使用各種級別創建 RAID，增加 RAID 組（陣列）和驅動器故障排除等。</p><hr>',52)),n("p",null,[i[1]||(i[1]=l("via: ",-1)),t(a,{href:"http://www.tecmint.com/understanding-raid-setup-in-linux/"},{default:I(()=>[...i[0]||(i[0]=[l("http://www.tecmint.com/understanding-raid-setup-in-linux/",-1)])]),_:1})]),n("p",null,[i[5]||(i[5]=l("作者：",-1)),t(a,{href:"http://www.tecmint.com/author/babinlonston/"},{default:I(()=>[...i[2]||(i[2]=[l("Babin Lonston",-1)])]),_:1}),i[6]||(i[6]=l(" 譯者：",-1)),t(a,{href:"https://github.com/strugglingyouth"},{default:I(()=>[...i[3]||(i[3]=[l("strugglingyouth",-1)])]),_:1}),i[7]||(i[7]=l(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:I(()=>[...i[4]||(i[4]=[l("wxy",-1)])]),_:1})]),n("p",null,[i[10]||(i[10]=l("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:I(()=>[...i[8]||(i[8]=[l("LCTT",-1)])]),_:1}),i[11]||(i[11]=l(" 原創翻譯，",-1)),t(a,{href:"https://linux.cn/"},{default:I(()=>[...i[9]||(i[9]=[l("Linux中國",-1)])]),_:1}),i[12]||(i[12]=l(" 榮譽推出",-1))])])}const f=e(p,[["render",o]]);export{T as __pageData,f as default};
